"""Linearizability checker for atomic range transactions.

A whole transaction is one atomic operation, so a witness is simply a
permutation of the transactions that (a) respects real time (if A.end <=
B.start then A precedes B) and (b) replays correctly from `initial` to
`final`.

Search: depth first over "which transaction runs next", carrying the
current state.  Feasibility of the future depends only on the set of still
unscheduled transactions and the current state, so failures are memoised.
Sound (never over-pruning) reductions used:

* state neutral transactions (e.g. read-only ones) that are currently
  runnable can always be moved to the front of the rest of the schedule,
  so they are scheduled greedily without branching;
* per key: the final value must be the current value or a value some
  remaining writer can produce;
* per pending transaction: for each key it constrains, some reachable
  value must satisfy its own reads.
"""

import json
import sys


def _code(v):
    """Map a value to a state symbol: 0 = absent, v+10 = present v."""
    return 0 if v is None else v + 10


def _apply(prog, state):
    """Run one transaction program against a state.

    Returns the new state tuple, or None if some observation mismatches.
    Op encodings (see solve):
      (0, idx, expected_code)                get
      (1, idx, code)                         put
      (2, idx)                               del
      (3, idx, old, new, want)               cas
      (4, [idx...], [(idx, code)...], smap)  scan
    """
    st = list(state)
    for o in prog:
        k = o[0]
        if k == 0:
            if st[o[1]] != o[2]:
                return None
        elif k == 1:
            st[o[1]] = o[2]
        elif k == 2:
            st[o[1]] = 0
        elif k == 3:
            ok = st[o[1]] == o[2]
            if ok != o[4]:
                return None
            if ok:
                st[o[1]] = o[3]
        else:
            act = []
            for i in o[1]:
                v = st[i]
                if v:
                    act.append((i, v))
            if act != o[2]:
                return None
    return tuple(st)


def solve(req):
    txs = req.get('transactions')
    if not txs:
        txs = []
    initial = req.get('initial') or {}
    final = req.get('final') or {}

    # ---------- normalise: keys, transaction programs ----------
    keyset = set(initial)
    keyset.update(final)
    norm = []
    for t in txs:
        lst = []
        for op in t['ops']:
            kind = op[0]
            if kind == 'get':
                keyset.add(op[1])
                lst.append((0, op[1], _code(op[2])))
            elif kind == 'put':
                keyset.add(op[1])
                lst.append((1, op[1], _code(op[2])))
            elif kind == 'del':
                keyset.add(op[1])
                lst.append((2, op[1]))
            elif kind == 'cas':
                keyset.add(op[1])
                want = op[4]
                if want is not True and want is not False:
                    # `ok is not want` can never hold -> tx can never run.
                    return {'order': None}
                lst.append((3, op[1], _code(op[2]), _code(op[3]), want))
            elif kind == 'scan':
                keyset.add(op[1])
                keyset.add(op[2])
                for pair in op[3]:
                    keyset.add(pair[0])
                lst.append((4, op[1], op[2], op[3]))
            else:
                return {'order': None}
        norm.append(lst)

    keys = sorted(keyset)
    K = len(keys)
    kidx = {}
    for i, k in enumerate(keys):
        kidx[k] = i
    init_state = tuple(_code(initial.get(k)) for k in keys)
    fs = tuple(_code(final.get(k)) for k in keys)
    n = len(norm)

    progs = []
    for lst in norm:
        prog = []
        for o in lst:
            kd = o[0]
            if kd == 4:
                low, high, pairs = o[1], o[2], o[3]
                inds = [i for i, k in enumerate(keys) if low <= k < high]
                exp = []
                smap = {}
                for p in pairs:
                    pi = kidx[p[0]]
                    pc = _code(p[1])
                    exp.append((pi, pc))
                    smap[pi] = pc
                prog.append((4, inds, exp, smap))
            else:
                prog.append((kd, kidx[o[1]]) + o[2:])
        progs.append(prog)

    # ---------- per key analysis ----------
    # every code a key can ever hold: its initial code plus every write.
    keycodes = [set() for _ in range(K)]
    for i in range(K):
        keycodes[i].add(init_state[i])
    for prog in progs:
        for o in prog:
            kd = o[0]
            if kd == 1:
                keycodes[o[1]].add(o[2])
            elif kd == 2:
                keycodes[o[1]].add(0)
            elif kd == 3:
                keycodes[o[1]].add(o[3])
    full_in = []
    for i in range(K):
        m = 0
        for c in keycodes[i]:
            m |= 1 << c
        full_in.append(m)

    writers = [0] * K          # transactions that can change key i
    outm = [[0] * n for _ in range(K)]   # codes key i may hold after tx t
    inm = [[0] * n for _ in range(K)]    # codes key i may hold before tx t
    inneed = []                # per tx: restricted (key, feasible-in mask)

    for t in range(n):
        prog = progs[t]
        need = []
        for i in range(K):
            fin = 0
            fout = 0
            touched = False
            for c in keycodes[i]:
                v = c
                ok = True
                for o in prog:
                    kd = o[0]
                    if kd == 0:                      # get
                        if o[1] == i and v != o[2]:
                            ok = False
                            break
                    elif kd == 1:                   # put
                        if o[1] == i:
                            v = o[2]
                            touched = True
                    elif kd == 2:                   # del
                        if o[1] == i:
                            v = 0
                            touched = True
                    elif kd == 3:                   # cas
                        if o[1] == i:
                            hit = v == o[2]
                            if hit != o[4]:
                                ok = False
                                break
                            if hit:
                                v = o[3]
                                touched = True
                    else:                           # scan
                        if i in o[1]:
                            if v != o[3].get(i, 0):
                                ok = False
                                break
                if ok:
                    fin |= 1 << c
                    fout |= 1 << v
                    if touched and v != c:
                        writers[i] |= 1 << t
            if fin == 0:
                # no possible value of key i lets this tx run at all
                return {'order': None}
            inm[i][t] = fin
            outm[i][t] = fout
            if fin != full_in[i]:
                need.append((i, fin))
        inneed.append(need)

    # ---------- real time precedence ----------
    pred = [0] * n
    for a in range(n):
        for b in range(n):
            if a != b and txs[a]['end'] <= txs[b]['start']:
                pred[b] |= 1 << a
    hint = sorted(range(n), key=lambda i: (txs[i]['start'], txs[i]['end'], i))

    full = (1 << n) - 1
    pmt = [dict() for _ in range(K)]   # (rem & writers[i]) -> code mask
    failed = set()

    def dfs(rem, state, progs=progs, pred=pred, hint=hint, wr=writers,
            pmt=pmt, outm=outm, inneed=inneed, failed=failed, fs=fs, K=K):
        if rem == 0:
            return [] if state == fs else None
        key = (rem, state)
        if key in failed:
            return None

        # ---- greedy: runnable transactions that leave the state alone ----
        sched = []
        cache = {}
        while True:
            found = False
            for t in hint:
                if not (rem >> t) & 1:
                    continue
                ns = cache.get(t, -1)
                if ns == -1:
                    if pred[t] & rem:
                        continue          # not runnable yet
                    ns = _apply(progs[t], state)
                    cache[t] = ns
                if ns == state:
                    sched.append(t)
                    rem &= ~(1 << t)
                    found = True
            if not found:
                break

        if rem == 0:
            if state == fs:
                return sched
            failed.add(key)
            return None

        # ---- prunes: possible values each key can still take ----
        pv = []
        for i in range(K):
            sub = rem & wr[i]
            tbl = pmt[i]
            r = tbl.get(sub)
            if r is None:
                r = 0
                mm = sub
                while mm:
                    low = mm & -mm
                    mm ^= low
                    r |= outm[i][low.bit_length() - 1]
                tbl[sub] = r
            pv.append(r)
        for i in range(K):
            if state[i] != fs[i] and not (pv[i] >> fs[i]) & 1:
                failed.add(key)
                failed.add((rem, state))
                return None

        # ---- prunes: pending transactions must still be able to run ----
        for t in hint:
            if (rem >> t) & 1:
                for (i, m) in inneed[t]:
                    if not m & ((1 << state[i]) | pv[i]):
                        failed.add(key)
                        failed.add((rem, state))
                        return None

        # ---- branch ----
        for t in hint:
            if (rem >> t) & 1 and not (pred[t] & rem):
                ns = cache.get(t, -1)
                if ns == -1:
                    ns = _apply(progs[t], state)
                if ns is not None and ns != state:
                    sub = dfs(rem & ~(1 << t), ns)
                    if sub is not None:
                        return sched + [t] + sub

        failed.add(key)
        failed.add((rem, state))
        return None

    res = dfs(full, init_state)
    if res is None:
        return {'order': None}
    return {'order': [txs[i]['id'] for i in res]}


def main():
    out = []
    for line in sys.stdin.read().splitlines():
        if not line.strip():
            continue
        out.append(json.dumps(solve(json.loads(line))))
    if out:
        sys.stdout.write('\n'.join(out) + '\n')


if __name__ == '__main__':
    main()
