"""Brute force reference: try every permutation, verify with the public contract."""
import itertools
from public_contract import valid_history


def brute(request):
    txs = request['transactions']
    ids = [t['id'] for t in txs]
    for p in itertools.permutations(ids):
        if valid_history(request, list(p)):
            return list(p)
    return None
