"""Random instance generator + differential test against brute force."""
import json, random, sys
from brute import brute
sys.path.insert(0, '/app')
from main import solve
from public_contract import valid_history

ALPHA = 'abcdefghijklmnop'


def gen_ops(rnd, keys, nops, state):
    """Generate nops operations, filling expected values from `state` (mutated)."""
    ops = []
    for _ in range(nops):
        kind = rnd.choice(['get', 'put', 'put', 'del', 'cas', 'scan'])
        k = rnd.choice(keys)
        if kind == 'get':
            ops.append(['get', k, state.get(k)])
        elif kind == 'put':
            v = rnd.choice([x for x in range(-3, 4)] + [None]) if rnd.random() < 0.1 \
                else rnd.randint(-3, 3)
            # put of a plain integer only (spec); occasionally None means delete
            if v is None:
                ops.append(['del', k])
            else:
                ops.append(['put', k, v])
                state[k] = v
        elif kind == 'del':
            ops.append(['del', k])
            state.pop(k, None)
        elif kind == 'cas':
            old = state.get(k) if rnd.random() < 0.7 else rnd.choice(
                [None] + [x for x in range(-3, 4)])
            ok = state.get(k) == old
            new = rnd.choice([None] + [x for x in range(-3, 4)])
            ops.append(['cas', k, old, new, ok])
            if ok:
                if new is None:
                    state.pop(k, None)
                else:
                    state[k] = new
        else:
            bounds = sorted(rnd.sample(ALPHA[:10], 2))
            pairs = sorted([[k, v] for k, v in state.items() if bounds[0] <= k < bounds[1]])
            ops.append(['scan', bounds[0], bounds[1], pairs])
    return ops


def gen(rnd, derive=True):
    nkeys = rnd.randint(1, 4)
    keys = sorted(rnd.sample(ALPHA[:8], nkeys))
    ntx = rnd.randint(0, 5)
    initial = {}
    for k in keys:
        if rnd.random() < 0.5:
            initial[k] = rnd.randint(-3, 3)
    txs = []
    for i in range(ntx):
        s = rnd.randint(0, 10)
        e = s + rnd.randint(1, 6)
        txs.append({'id': 't%d' % i, 'start': s, 'end': e, 'ops': []})
    # pick a real-time consistent order and derive observations
    order = list(range(ntx))
    rnd.shuffle(order)
    # fix real time: insertion sort by precedence
    for _ in range(200):
        a, b = rnd.sample(range(ntx), 2) if ntx > 1 else (0, 0)
        if ntx > 1 and txs[a]['end'] <= txs[b]['start'] and order.index(a) > order.index(b):
            order.remove(a)
            order.insert(order.index(b), a)
    state = dict(initial)
    if derive:
        for i in order:
            t = txs[i]
            nops = rnd.randint(1, 4)
            t['ops'] = gen_ops(rnd, keys, nops, state)
        final = dict(state)
    else:
        for i in order:
            t = txs[i]
            nops = rnd.randint(1, 4)
            t['ops'] = gen_ops(rnd, keys, nops, state)
        final = dict(state)
    req = {'initial': initial, 'final': final, 'transactions': txs}
    # mutation to break validity sometimes
    if rnd.random() < 0.55:
        m = rnd.choice(['get', 'cas', 'scan', 'final', 'final2'])
        cand = [t for t in txs if t['ops']]
        if m == 'get':
            for t in txs:
                for op in t['ops']:
                    if op[0] == 'get' and rnd.random() < 0.5:
                        op[2] = None if op[2] is not None else rnd.randint(-3, 3)
        elif m == 'cas' and cand:
            for t in txs:
                for op in t['ops']:
                    if op[0] == 'cas' and rnd.random() < 0.4:
                        op[4] = not op[4]
        elif m == 'scan':
            for t in txs:
                for op in t['ops']:
                    if op[0] == 'scan' and rnd.random() < 0.5:
                        if op[3] and rnd.random() < 0.5:
                            op[3] = op[3][:-1]
                        else:
                            kk = rnd.choice(keys)
                            op[3] = sorted(op[3] + [[kk, rnd.randint(-3, 3)]])
        elif m == 'final':
            if final and rnd.random() < 0.5:
                final.pop(rnd.choice(list(final)))
            else:
                final[rnd.choice(keys)] = rnd.randint(-3, 3)
        else:
            req['final'] = dict(final)
            req['final'][rnd.choice(keys)] = rnd.randint(-9, 9)
    return req


def run(iters, seed0, derive=True):
    rnd = random.Random(seed0)
    bad = 0
    stats = {'null': 0, 'ok': 0}
    for it in range(iters):
        req = gen(rnd, derive)
        got = solve(req)
        exp = brute(req)
        if exp is None:
            stats['null'] += 1
            if got['order'] is not None:
                # maybe still valid? brute says no
                print('MISMATCH: solver found order, brute says none')
                print(json.dumps(req))
                bad += 1
        else:
            if got['order'] is None:
                print('MISMATCH: solver says none, brute found', exp)
                print(json.dumps(req))
                bad += 1
            elif not valid_history(req, got['order']):
                print('MISMATCH: solver order invalid')
                print(json.dumps(req), got)
                bad += 1
            else:
                stats['ok'] += 1
    print('done', iters, 'bad', bad, stats)
    return bad


if __name__ == '__main__':
    iters = int(sys.argv[1]) if len(sys.argv) > 1 else 2000
    seed = int(sys.argv[2]) if len(sys.argv) > 2 else 1
    derive = (len(sys.argv) <= 3) or sys.argv[3] != 'raw'
    sys.exit(1 if run(iters, seed, derive) else 0)
