"""Aggressive random differential test vs brute force."""
import json, random, sys
from brute import brute
from main import solve
from public_contract import valid_history

ALPHA = 'abcdefghijklmnopqrstuvwxyz'


def gen(rnd, ntx_max=6, nkey_max=6, nops_max=5, span=8, valrange=9):
    nkeys = rnd.randint(1, nkey_max)
    keys = sorted(rnd.sample(ALPHA[:12], nkeys))
    ntx = rnd.randint(0, ntx_max)
    initial = {k: rnd.randint(-valrange, valrange) for k in keys if rnd.random() < 0.5}
    txs = []
    for i in range(ntx):
        s = rnd.randint(0, span)
        e = s + rnd.randint(1, span)
        txs.append({'id': 'tx%d' % i, 'start': s, 'end': e, 'ops': []})
    order = list(range(ntx))
    rnd.shuffle(order)
    for _ in range(300):   # enforce real-time order in `order`
        for a in range(ntx):
            for b in range(ntx):
                if a != b and txs[a]['end'] <= txs[b]['start'] and order.index(a) > order.index(b):
                    order.remove(a)
                    order.insert(order.index(b), a)
    state = dict(initial)
    raw = rnd.random() < 0.3   # random (usually wrong) expectations
    for i in order:
        ops = []
        for _ in range(rnd.randint(1, nops_max)):
            kind = rnd.choice(['get', 'get', 'put', 'put', 'del', 'cas', 'scan'])
            k = rnd.choice(keys)
            if kind == 'get':
                exp = state.get(k) if not raw else rnd.choice([None] + list(range(-valrange, valrange + 1)))
                ops.append(['get', k, exp])
            elif kind == 'put':
                v = rnd.randint(-valrange, valrange)
                ops.append(['put', k, v])
                state[k] = v
            elif kind == 'del':
                ops.append(['del', k])
                state.pop(k, None)
            elif kind == 'cas':
                old = state.get(k) if rnd.random() < 0.7 else rnd.choice([None] + list(range(-valrange, valrange + 1)))
                ok = state.get(k) == old
                new = rnd.choice([None] + list(range(-valrange, valrange + 1)))
                want = ok if not raw else rnd.random() < 0.5
                ops.append(['cas', k, old, new, want])
                if want and ok:
                    if new is None:
                        state.pop(k, None)
                    else:
                        state[k] = new
            else:
                bs = sorted(rnd.sample(ALPHA[:14], 2))
                pairs = sorted([[kk, vv] for kk, vv in state.items() if bs[0] <= kk < bs[1]])
                if raw and rnd.random() < 0.5:
                    pairs = sorted(pairs + [[rnd.choice(keys), rnd.randint(-valrange, valrange)]])
                ops.append(['scan', bs[0], bs[1], pairs])
        txs[i]['ops'] = ops
    final = dict(state)
    if rnd.random() < 0.5:
        if final and rnd.random() < 0.5:
            final.pop(rnd.choice(list(final)))
        else:
            final[rnd.choice(keys)] = rnd.randint(-valrange, valrange)
    return {'initial': initial, 'final': final, 'transactions': txs}


def run(iters, seed, **kw):
    rnd = random.Random(seed)
    bad = 0
    nnull = nok = 0
    for it in range(iters):
        req = gen(rnd, **kw)
        got = solve(req)
        exp = brute(req)
        if exp is None:
            nnull += 1
            if got['order'] is not None:
                bad += 1
                print('MISMATCH solver-order brute-none', json.dumps(req)); break
        else:
            if got['order'] is None:
                bad += 1
                print('MISMATCH solver-none brute-found', json.dumps(req), exp); break
            if not valid_history(req, got['order']):
                bad += 1
                print('MISMATCH solver-order-invalid', json.dumps(req), got); break
            nok += 1
    print('iters', it + 1, 'bad', bad, 'witness', nok, 'none', nnull)
    return bad


if __name__ == '__main__':
    iters = int(sys.argv[1]) if len(sys.argv) > 1 else 500
    seed = int(sys.argv[2]) if len(sys.argv) > 2 else 7
    sys.exit(1 if run(iters, seed) else 0)
