import json, random, time, sys
from main import solve

def mk(rnd, ntx=10, nkeys=6, nops=5, overlapping=True, impossible=True, reads=0.0, cas=0.0, scan=0.0):
    keys = ['k%d' % i for i in range(nkeys)]
    initial = {}
    txs = []
    for i in range(ntx):
        if overlapping:
            s, e = 0, 100
        else:
            s = rnd.randint(0, 50); e = s + rnd.randint(1, 5)
        ops = []
        for _ in range(nops):
            r = rnd.random()
            if r < reads:
                ops.append(['get', rnd.choice(keys), rnd.randint(-9, 9)])
            elif r < reads + cas:
                ops.append(['cas', rnd.choice(keys), rnd.randint(-9, 9), rnd.randint(-9, 9), True])
            elif r < reads + cas + scan:
                a, b = sorted(rnd.sample('abcdefgh', 2))
                ops.append(['scan', a, b, []])
            else:
                ops.append(['put', rnd.choice(keys), rnd.randint(-9, 9)])
        txs.append({'id': 't%d' % i, 'start': s, 'end': e, 'ops': ops})
    # final = a state that is reachable-ish, or an impossible one
    final = {k: rnd.randint(-9, 9) for k in keys if rnd.random() < 0.7}
    if impossible:
        final['zz'] = 5   # never written -> unreachable
    return {'initial': initial, 'final': final, 'transactions': txs}

def bench(name, reqs):
    t0 = time.perf_counter()
    for r in reqs:
        solve(r)
    dt = time.perf_counter() - t0
    print('%-38s n=%3d total=%7.3fs per=%8.4fms' % (name, len(reqs), dt, dt / len(reqs) * 1000))

rnd = random.Random(5)
bench('10tx/6keys/5put overlap impossible', [mk(rnd) for _ in range(20)])
bench('10tx/6keys/5put nonoverlap impossible', [mk(rnd, overlapping=False) for _ in range(20)])
bench('10tx/6keys/5ops 30%reads impossible', [mk(rnd, reads=0.3) for _ in range(20)])
bench('10tx/6keys/5ops 30%cas impossible', [mk(rnd, cas=0.3) for _ in range(20)])
bench('10tx/6keys/5ops 30%scan impossible', [mk(rnd, scan=0.3) for _ in range(20)])
bench('10tx/6keys/5put overlap possible', [mk(rnd, impossible=False) for _ in range(20)])
bench('10tx/2keys/5put overlap impossible', [mk(rnd, nkeys=2) for _ in range(20)])
bench('10tx/6keys/1put overlap impossible', [mk(rnd, nops=1) for _ in range(20)])
