"""Linearizability checker for atomic range transactions.

A transaction is one atomic step, so a witness is a permutation of the
transactions that respects real time (A.end <= B.start forces A before B)
and replays from `initial` to `final` with every observation matching.

Method
------
Search depth first over "which transaction runs next", carrying the current
state.  Whether the rest can be completed depends only on the set of still
unscheduled transactions and on the state, so failures are memoised.

Three observations make this fast and keep it exact:

* Every operation constrains/updates exactly one key, and a scan is
  equivalent to one "key must hold this value" test per key in its range
  (a malformed scan can never succeed at all).  So a transaction's effect
  and validity factorise per key, and can be precompiled into one
  transition table per (transaction, key): symbol -> symbol, or invalid.
  The state itself is a packed integer, one field per key.

* A transaction that cannot change any key and is runnable now can always
  be moved to the front of the rest of the schedule, so such transactions
  are scheduled greedily instead of being branched on.

* If no unscheduled transaction reads a key but some unscheduled one still
  writes it, the current value of that key cannot influence the rest of the
  run (the final value is decided by the last writer).  Such fields are
  masked out of the memo key, which collapses large parts of the search.

Sound (never over-pruning) tests cut off hopeless branches: a key whose
final value no remaining writer can produce, and a pending transaction
whose reads no reachable value can satisfy.
"""

import json
import sys


def _solve(req):
    txs = req.get('transactions')
    if not txs:
        txs = []
    initial = req.get('initial') or {}
    final = req.get('final') or {}

    # ---------------- keys, symbols, normalised operations ----------------
    # symbol 0 means "absent"; every distinct value gets its own symbol, so
    # absent is always different from a key holding zero.
    symmap = {None: 0}

    def sym(v):
        s = symmap.get(v)
        if s is None:
            s = len(symmap)
            symmap[v] = s
        return s

    for v in initial.values():
        sym(v)
    for v in final.values():
        sym(v)

    keys = set(initial)
    keys.update(final)
    raws = []
    for t in txs:
        raw = []
        for op in t['ops']:
            kind = op[0]
            if kind == 'get':
                keys.add(op[1])
                raw.append((0, op[1], sym(op[2])))
            elif kind == 'put':
                keys.add(op[1])
                raw.append((1, op[1], sym(op[2])))
            elif kind == 'del':
                keys.add(op[1])
                raw.append((1, op[1], 0))
            elif kind == 'cas':
                keys.add(op[1])
                want = op[4]
                if want is not True and want is not False:
                    return {'order': None}      # `ok is not want` always holds
                raw.append((2, op[1], sym(op[2]), sym(op[3]), want))
            elif kind == 'scan':
                low, high, pairs = op[1], op[2], op[3]
                keys.add(low)
                keys.add(high)
                seen = []
                prev = None
                for p in pairs:
                    if not isinstance(p, (list, tuple)) or len(p) != 2:
                        return {'order': None}
                    kk, vv = p[0], p[1]
                    # the answer is always sorted, unique, in range, non-null
                    if vv is None or not low <= kk < high or (prev is not None and prev >= kk):
                        return {'order': None}
                    keys.add(kk)
                    seen.append((kk, sym(vv)))
                    prev = kk
                raw.append((3, low, high, seen))
            else:
                return {'order': None}
        raws.append(raw)

    keys = sorted(keys)
    K = len(keys)
    kidx = {}
    for i, k in enumerate(keys):
        kidx[k] = i
    n = len(raws)

    # flat programs: (0, key, sym) test, (1, key, sym) assign, (2, key, old,
    # new, want) cas.  A scan becomes one test per key inside its range.
    progs = []
    for raw in raws:
        prog = []
        for o in raw:
            kd = o[0]
            if kd == 3:
                low, high, seen = o[1], o[2], o[3]
                want = dict(seen)
                for i, k in enumerate(keys):
                    if low <= k < high:
                        prog.append((0, i, want.get(k, 0)))
            else:
                prog.append((kd, kidx[o[1]]) + o[2:])
        progs.append(prog)

    # ---------------- per (transaction, key) transition tables -------------
    # every symbol a key can ever hold: its initial symbol plus every write
    keycodes = []
    for i in range(K):
        keycodes.append(set())
    for prog in progs:
        for o in prog:
            if o[0] == 1:
                keycodes[o[1]].add(o[2])
            elif o[0] == 2:
                keycodes[o[1]].add(o[3])
    init_int = 0
    fs_int = 0
    for i in range(K):
        keycodes[i].add(0 if i else 0)      # placeholder, fixed below
    # initial symbols
    init_syms = [sym(initial.get(k)) for k in keys]
    fin_syms = [sym(final.get(k)) for k in keys]
    for i in range(K):
        keycodes[i].add(init_syms[i])
    full_in = []
    for i in range(K):
        m = 0
        for c in keycodes[i]:
            m |= 1 << c
        full_in.append(m)

    W = max(1, (len(symmap) - 1).bit_length())
    SM = (1 << W) - 1
    sh = [W * i for i in range(K)]
    vm = [SM << s for s in sh]
    for i in range(K):
        init_int |= init_syms[i] << sh[i]
        fs_int |= fin_syms[i] << sh[i]

    writers = [0] * K     # transactions that can change key i
    readers = [0] * K     # transactions that test key i
    outm = [[0] * n for _ in range(K)]   # symbols key i may hold after tx t
    inm = [[0] * n for _ in range(K)]    # symbols key i may hold before tx t
    tabs_all = []
    inneed = []
    for t in range(n):
        prog = progs[t]
        touched = []
        seen = {}
        for o in prog:
            if o[1] not in seen:
                seen[o[1]] = None
                touched.append(o[1])
        tabs = []
        need = []
        for i in touched:
            ops_i = [o for o in prog if o[1] == i]
            tab = [-1] * len(symmap)
            fin = 0
            fout = 0
            tests = False
            for o in ops_i:
                if o[0] != 1:
                    tests = True
                    break
            for c in keycodes[i]:
                v = c
                ok = True
                for o in ops_i:
                    kd = o[0]
                    if kd == 0:
                        if v != o[2]:
                            ok = False
                            break
                    elif kd == 1:
                        v = o[2]
                    else:
                        hit = v == o[2]
                        if hit != o[4]:
                            ok = False
                            break
                        if hit:
                            v = o[3]
                if ok:
                    tab[c] = v
                    fin |= 1 << c
                    fout |= 1 << v
                    if v != c:
                        writers[i] |= 1 << t
            if fin == 0:
                return {'order': None}     # no value lets this tx run
            if tests:
                readers[i] |= 1 << t
            inm[i][t] = fin
            outm[i][t] = fout
            tabs.append((sh[i], vm[i], tab))
            if fin != full_in[i]:
                need.append((i, fin))
        tabs_all.append(tuple(tabs))
        inneed.append(tuple(need))

    # ---------------- real time precedence ----------------
    pred = [0] * n
    for a in range(n):
        for b in range(n):
            if a != b and txs[a]['end'] <= txs[b]['start']:
                pred[b] |= 1 << a
    hint = sorted(range(n), key=lambda i: (txs[i]['start'], txs[i]['end'], i))
    full = (1 << n) - 1
    noop = full
    for i in range(K):
        noop &= ~writers[i]

    # static reachability of each final value
    for i in range(K):
        if init_syms[i] != fin_syms[i]:
            w = writers[i]
            m = 0
            while w:
                low = w & -w
                w ^= low
                m |= outm[i][low.bit_length() - 1]
            if not m & (1 << fin_syms[i]):
                return {'order': None}

    # ---------------- search ----------------
    def apply(tabs, state, SM=SM):
        new = state
        for s, v, tab in tabs:
            c = (state >> s) & SM
            r = tab[c]
            if r < 0:
                return None
            if r != c:
                new = (new & ~v) | (r << s)
        return new

    pmt = [dict() for _ in range(K)]    # (rem & writers[i]) -> symbol mask
    care = {}                           # rem -> mask of fields that matter
    failed = set()
    wr = writers
    rd = readers
    risky = tuple(i for i in range(K) if wr[i])
    riskymask = 0
    for i in risky:
        riskymask |= vm[i]
    need_txs = tuple(t for t in range(n) if inneed[t])
    finbit = [1 << f for f in fin_syms]

    def dfs(rem, state, tabs=tabs_all, pred=pred, hint=hint, wr=wr, rd=rd,
            pmt=pmt, outm=outm, inneed=inneed, failed=failed, fs=fs_int,
            K=K, noop=noop, apply=apply, care=care, risky=risky,
            riskymask=riskymask, need_txs=need_txs, finbit=finbit,
            vm=vm, sh=sh, SM=SM, full=full):
        if rem == 0:
            return [] if state == fs else None
        cm = care.get(rem)
        if cm is None:
            cm = 0
            for i in range(K):
                if not (rem & rd[i]) and (rem & wr[i]):
                    continue          # value of this key cannot matter
                cm |= vm[i]
            care[rem] = cm
        key = (rem, state & cm)
        if key in failed:
            return None

        # ---- greedy: runnable transactions that never change any key ----
        sched = []
        cache = {}
        while True:
            found = False
            for t in hint:
                if (rem >> t) & 1 and (noop >> t) & 1:
                    ns = cache.get(t, -1)
                    if ns == -1:
                        if pred[t] & rem:
                            continue
                        ns = apply(tabs[t], state)
                        cache[t] = ns
                    if ns is not None:
                        sched.append(t)
                        rem &= ~(1 << t)
                        found = True
            if not found:
                break
        if rem == 0:
            if state == fs:
                return sched
            failed.add(key)
            return None
        cm = care.get(rem)
        if cm is None:
            cm = 0
            for i in range(K):
                if not (rem & rd[i]) and (rem & wr[i]):
                    continue
                cm |= vm[i]
            care[rem] = cm
        key2 = (rem, state & cm)
        if key2 in failed:
            failed.add(key)
            return None

        # ---- possible symbol per key for the remaining writers ----
        pv = []
        for i in range(K):
            sub = rem & wr[i]
            if sub:
                tbl = pmt[i]
                r = tbl.get(sub)
                if r is None:
                    r = 0
                    mm = sub
                    oi = outm[i]
                    while mm:
                        low = mm & -mm
                        mm ^= low
                        r |= oi[low.bit_length() - 1]
                    tbl[sub] = r
                pv.append(r)
            else:
                pv.append(0)

        # ---- a key whose final symbol no remaining writer produces ----
        diff = state ^ fs
        if diff & riskymask:
            for i in risky:
                if diff & vm[i] and not pv[i] & finbit[i]:
                    failed.add(key)
                    failed.add(key2)
                    return None

        # ---- a pending transaction whose reads cannot be satisfied ----
        for t in need_txs:
            if (rem >> t) & 1:
                for i, m in inneed[t]:
                    if not m & ((1 << ((state >> sh[i]) & SM)) | pv[i]):
                        failed.add(key)
                        failed.add(key2)
                        return None

        # ---- branch on runnable transactions ----
        for t in hint:
            if (rem >> t) & 1 and not (pred[t] & rem) and not (noop >> t) & 1:
                ns = apply(tabs[t], state)
                if ns is not None:
                    sub = dfs(rem & ~(1 << t), ns)
                    if sub is not None:
                        return sched + [t] + sub

        failed.add(key)
        failed.add(key2)
        return None

    res = dfs(full, init_int)
    if res is None:
        return {'order': None}
    return {'order': [txs[i]['id'] for i in res]}


def solve(req):
    try:
        return _solve(req)
    except Exception:                      # malformed input: no witness
        return {'order': None}


def main():
    out = []
    for line in sys.stdin.read().splitlines():
        if not line.strip():
            continue
        out.append(json.dumps(solve(json.loads(line))))
    if out:
        sys.stdout.write('\n'.join(out) + '\n')


if __name__ == '__main__':
    main()
