"""Search many instance shapes for the worst solve time."""
import json, random, sys, time
from main import solve
from public_contract import valid_history

KEYS = ['k%d' % i for i in range(6)]

def gen(rnd, ntx=10, nkeys=6, nops=5, mix=('put', 'get', 'cas', 'scan'),
        weights=(0.5, 0.2, 0.2, 0.1), overlap=1.0, mutate=0.0, span=6):
    keys = KEYS[:nkeys]
    ntx = ntx
    txs = []
    for i in range(ntx):
        if rnd.random() < overlap:
            s, e = 0, 100
        else:
            s = rnd.randint(0, 40)
            e = s + rnd.randint(1, span)
        txs.append({'id': 't%d' % i, 'start': s, 'end': e, 'ops': []})
    order = list(range(ntx))
    rnd.shuffle(order)
    for _ in range(400):
        for a in range(ntx):
            for b in range(ntx):
                if a != b and txs[a]['end'] <= txs[b]['start'] and order.index(a) > order.index(b):
                    order.remove(a); order.insert(order.index(b), a)
    state = {}
    for k in keys:
        if rnd.random() < 0.4:
            state[k] = rnd.randint(-9, 9)
    initial = dict(state)
    writes = {}
    for i in order:
        ops = []
        for _ in range(rnd.randint(1, nops)):
            kind = rnd.choices(mix, weights)[0]
            k = rnd.choice(keys)
            if kind == 'get':
                ops.append(['get', k, state.get(k)])
            elif kind == 'put':
                v = rnd.randint(-9, 9)
                ops.append(['put', k, v]); state[k] = v
                writes.setdefault(k, set()).add(v)
            elif kind == 'del':
                ops.append(['del', k]); state.pop(k, None)
                writes.setdefault(k, set()).add(0)
            elif kind == 'cas':
                old = state.get(k)
                ok = state.get(k) == old
                new = rnd.choice([None] + [rnd.randint(-9, 9) for _ in range(3)])
                ops.append(['cas', k, old, new, True])
                if new is None: state.pop(k, None)
                else: state[k] = new; writes.setdefault(k, set()).add(new)
            else:
                a, b = sorted(rnd.sample('abcdefghij', 2))
                ops.append(['scan', a, b, sorted([[kk, vv] for kk, vv in state.items() if a <= kk < b])])
        txs[i]['ops'] = ops
    final = dict(state)
    if mutate and rnd.random() < mutate:
        if rnd.random() < 0.5 and final:
            final.pop(rnd.choice(list(final)))
        else:
            final[rnd.choice(keys)] = rnd.choice(list(writes.get(rnd.choice(list(writes)), {1})) or [1])
    return {'initial': initial, 'final': final, 'transactions': txs}

def sweep(rnd, N, **kw):
    worst = (0.0, None)
    tot = 0.0
    nnull = 0
    for i in range(N):
        req = gen(rnd, **kw)
        t0 = time.perf_counter()
        r = solve(req)
        dt = time.perf_counter() - t0
        tot += dt
        if r['order'] is None:
            nnull += 1
        elif not valid_history(req, r['order']):
            print('INVALID ORDER!', json.dumps(req)); sys.exit(1)
        if dt > worst[0]:
            worst = (dt, req)
    return tot / N, worst, nnull

rnd = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 2)
N = int(sys.argv[2]) if len(sys.argv) > 2 else 150
configs = [
    dict(),                                                     # default derived
    dict(weights=(0.5, 0.2, 0.2, 0.1), overlap=1.0),
    dict(weights=(0.34, 0.33, 0.33, 0.0)),                     # no scans
    dict(weights=(0.25, 0.25, 0.25, 0.25)),
    dict(weights=(0.7, 0.1, 0.1, 0.1), overlap=1.0, mutate=1.0),
    dict(weights=(0.5, 0.2, 0.2, 0.1), overlap=0.5, span=2),
    dict(weights=(0.5, 0.2, 0.2, 0.1), overlap=1.0, mutate=1.0, nops=5),
    dict(nkeys=2, weights=(0.5, 0.2, 0.2, 0.1)),
    dict(nkeys=3, weights=(0.4, 0.2, 0.2, 0.2)),
    dict(weights=(0.2, 0.4, 0.2, 0.2)),                        # read heavy
    dict(weights=(0.1, 0.6, 0.1, 0.2)),                        # very read heavy
    dict(weights=(0.45, 0.1, 0.45, 0.0)),                     # cas heavy
    dict(weights=(0.4, 0.1, 0.1, 0.4)),                        # scan heavy
]
for c in configs:
    mean, worst, nnull = sweep(rnd, N, **c)
    print('%-58s mean=%7.3fms worst=%8.3fms nulls=%d/%d' % (
        json.dumps(c, sort_keys=True), mean * 1000, worst[0] * 1000, nnull, N))
    if worst[0] > 0.02:
        json.dump(worst[1], open('/tmp/worst_%d.json' % int(worst[0] * 1000), 'w'))
