"""Independent reference: plain forward DP over (scheduled set, dict state).

Deliberately naive: no prunes, no abstraction, state is a sorted tuple of
the dict items, and each transaction is replayed exactly the way the public
contract replays it.
"""


def run_tx(t, d):
    d = dict(d)
    for op in t['ops']:
        k = op[0]
        if k == 'get':
            if d.get(op[1]) != op[2]:
                return None
        elif k == 'put':
            d[op[1]] = op[2]
        elif k == 'del':
            d.pop(op[1], None)
        elif k == 'cas':
            ok = d.get(op[1]) == op[2]
            if ok is not op[4]:
                return None
            if ok:
                if op[3] is None:
                    d.pop(op[1], None)
                else:
                    d[op[1]] = op[3]
        else:
            if sorted([[kk, vv] for kk, vv in d.items() if op[1] <= kk < op[2]]) != op[3]:
                return None
    return d


def ref_solve(req):
    txs = req['transactions']
    n = len(txs)
    pred = [set() for _ in range(n)]
    for a in range(n):
        for b in range(n):
            if a != b and txs[a]['end'] <= txs[b]['start']:
                pred[b].add(a)
    start = tuple(sorted(req['initial'].items()))
    layers = [{frozenset(): {start}}]
    for k in range(n):
        nxt = {}
        for S, states in layers[k].items():
            for t in range(n):
                if t in S or not pred[t] <= S:
                    continue
                newS = S | {t}
                out = nxt.setdefault(newS, set())
                for st in states:
